function HouseMineMainPanelVM:ChangePage()
    self.CommEmptyVisibility = false
    self.SharingpermissionsPanelVisibility = false
    self.InvitePanelVisibility = false
    self.InfoPanelVisibility = false
    self.RoomAllPanelVisibility = false
    self.SettingsPanelVisibility = false

    if self.PageNum == 0 or self.PageNum == 2 then -- 个人房屋 部队房屋的信息
        self.InfoPanelVisibility = true 
    elseif self.PageNum == 1 then
        self.SettingsPanelVisibility = true
    elseif self.PageNum == 3 then   --- 个人房间的信息
        self.InfoPanelVisibility = _G.HouseInfoMgr.MajorMemberHouseID > 0 
        self.CommEmptyVisibility = _G.HouseInfoMgr.MajorMemberHouseID <= 0 
    elseif self.PageNum == 4 then
        self.RoomAllPanelVisibility = true
    elseif self.PageNum == 5 then
        if _G.HouseInfoMgr.SharedHouseID > 0 then
            self.InfoPanelVisibility = true
        else
            self.InvitePanelVisibility = true
        end
    elseif self.PageNum == 6 then
        self.SharingpermissionsPanelVisibility = true
    else

    end
end

function HouseMineMainPanelVM:GetKeyByPageNum()
    if self.PageNum == 0 or self.PageNum == 1 then
        return 1
    elseif self.PageNum == 2 or self.PageNum == 3 or self.PageNum == 4 then
        return 2
    else
        return 3
    end
end

function HouseMineMainPanelVM:GetPageNumBySubItemKey(Key)
    if Key >= 4 or Key <= 11 then
        return Key - 4
