end

function HouseMineMainPanelVM:UpdateTabList()
    self.TabList = {}
    if _G.HouseInfoMgr.HasMajorHouse == true then
        table.insert(self.TabList, self.MajorHouseInfoList)
    end
    if _G.HouseInfoMgr.HasArmyHouse == true then
        if _G.ArmyMgr:GetArmyLevel() == 10 then                --TODO 目前部队最高8级 后续改成10级
            self.ArmyHouseInfoList.Children[2].IsUnLock = true
            self.ArmyHouseInfoList.Children[3].IsUnLock = true
        else
            self.ArmyHouseInfoList.Children[2].IsUnLock = false
            self.ArmyHouseInfoList.Children[3].IsUnLock = false
            self.ArmyHouseInfoList.Children[2].AlwaysSelect = true
            self.ArmyHouseInfoList.Children[3].AlwaysSelect = true
        end 
        table.insert(self.TabList, self.ArmyHouseInfoList)
    end
    table.insert(self.TabList, self.ShareHouseInfoList)
end

function HouseMineMainPanelVM:SelectTabList(SelectList, Key)
    self.TabList = {}
    if Key and Key > 0 then
        self.SelectKey = Key
    end
    for _,v in ipairs(SelectList) do
        if v == 1 then
            table.insert(self.TabList, self.MajorHouseInfoList)
        elseif v == 2 then
            if _G.ArmyMgr:GetArmyLevel() == 10 then                --TODO 目前部队最高8级 后续改成10级
                self.ArmyHouseInfoList.Children[2].IsUnLock = true
                self.ArmyHouseInfoList.Children[3].IsUnLock = true
            else
                self.ArmyHouseInfoList.Children[2].IsUnLock = false
                self.ArmyHouseInfoList.Children[3].IsUnLock = false
            end
            table.insert(self.TabList, self.ArmyHouseInfoList)
        elseif v == 3 then
            table.insert(self.TabList, self.ShareHouseInfoList)
        end
    end
end


return HouseMineMainPanelVM
